from fixtures import ROWS
from parsing import parse_fixtures

LINES = ["%s,%s" % (k, v) for k, v in ROWS]


def test_all_lines():
    records = parse_fixtures("\n".join(LINES))
    assert [(x.club, x.goals) for x in records] == [(k, v) for k, v in ROWS]


def test_trailing_newline():
    assert len(parse_fixtures("\n".join(LINES) + "\n")) == len(ROWS)


def test_blank_lines():
    assert len(parse_fixtures(LINES[0] + "\n\n" + LINES[1] + "\n  ")) == 2


def test_single_line():
    assert len(parse_fixtures(LINES[0])) == 1


def test_empty_text():
    assert parse_fixtures("") == []

