def parse_fixtures(text):
    """Parse lines of 'club,goals' into Fixture records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    if line.strip():
        out.append(_parse_line(line))
    return out
